UPDATE site_content
SET content_json = json_set(content_json, '$.intranet', json('{"title":"Intranet Hy-Line do Brasil","intro":"Acesso r\u00e1pido aos ambientes internos, aplicativos e sistemas de apoio usados pela equipe Hy-Line do Brasil.","links":[{"slug":"aplicativo-web-desktop","title":"Aplicativo WEB - Desktop","category":"Sistema interno","description":"Acesso ao aplicativo web para uso em computadores e esta\u00e7\u00f5es de trabalho.","accessText":"\u00c1rea de direcionamento para usu\u00e1rios autorizados acessarem o aplicativo web em desktop. Quando o endere\u00e7o final do sistema for confirmado, ele pode ser inserido no campo externalUrl pelo painel."},{"slug":"aplicativos-web-mobile","title":"Aplicativos WEB - Mobile","category":"Sistema interno","description":"Acesso aos aplicativos web voltados para uso em celulares e tablets.","accessText":"Atalho interno para orientar o acesso mobile aos aplicativos web usados pela equipe Hy-Line."},{"slug":"agenda-projetores","title":"Agenda - Projetores","category":"Opera\u00e7\u00e3o interna","description":"Consulta e organiza\u00e7\u00e3o de agenda para uso de projetores e recursos internos.","accessText":"Espa\u00e7o de apoio para reserva, consulta e organiza\u00e7\u00e3o de projetores e recursos internos."},{"slug":"fluig","title":"Fluig","category":"Sistema interno","description":"Acesso ao ambiente Fluig utilizado para processos e rotinas internas.","accessText":"Direcionamento para o ambiente Fluig da Hy-Line, utilizado em fluxos, processos e rotinas administrativas internas."},{"slug":"aplicativo-de-granjas","title":"Aplicativo de Granjas (Farm App)","category":"Opera\u00e7\u00e3o interna","description":"Atalho para ferramentas internas relacionadas \u00e0 rotina das granjas.","accessText":"Acesso organizado para ferramentas de apoio \u00e0 rotina operacional das granjas e registros internos."},{"slug":"poultry-suite","title":"Poultry Su\u00edte","category":"Gest\u00e3o t\u00e9cnica","description":"Acesso ao ambiente de apoio t\u00e9cnico e operacional da plataforma Poultry Su\u00edte.","accessText":"Ambiente de apoio t\u00e9cnico e operacional para consultas e gest\u00e3o de informa\u00e7\u00f5es relacionadas \u00e0 produ\u00e7\u00e3o."}]}')),
